let prefix = String.lowercase_ascii Policy.name
let refused_unit = Policy.name ^ "__Refused"
let overflow = "Unreviewed"
let unit_module m = Policy.name ^ "__" ^ m

let header =
  Printf.sprintf
    "(* Generated by lib/gen from lib/gen/policy.ml and the standard library of\n\
    \   OCaml %s. Do not edit. *)\n\n"
    Sys.ocaml_version

let keywords = [ "or"; "mod"; "land"; "lor"; "lxor"; "lsl"; "lsr"; "asr" ]

let value_name v =
  let ident = function
    | 'a' .. 'z' | 'A' .. 'Z' | '0' .. '9' | '_' | '\'' -> true
    | _ -> false
  in
  if String.for_all ident v && not (List.mem v keywords) then v
  else "( " ^ v ^ " )"

let line buf depth fmt =
  Printf.ksprintf
    (fun s ->
      if s <> "" then Buffer.add_string buf (String.make (2 * depth) ' ');
      Buffer.add_string buf s;
      Buffer.add_char buf '\n')
    fmt

let comment = Doc.comment

(* {1 Units} *)

(* The top-level modules that have a unit of their own: every one the policy
   names, by a refusal or as an alias of restated modules. A restated module
   the policy does not name, which only a newer compiler has, goes to the
   overflow unit. *)
let units =
  let heads =
    List.filter_map
      (fun (path, _) ->
        let head = List.hd (String.split_on_char '.' path) in
        if head <> "" && Char.uppercase_ascii head.[0] = head.[0] then Some head
        else None)
      Policy.refusals
  in
  List.sort_uniq String.compare (heads @ Policy.aliases)

let unit_path m =
  if List.mem m units then unit_module m else unit_module overflow ^ "." ^ m

(* Whether the source being emitted is the overflow unit's, in which a module
   of the overflow unit is named directly. *)
let in_overflow = ref false

(* The prelude's module at a policy path: [Random.State] is
   [Hermetic__Random.State]. *)
let restated_path path =
  match String.split_on_char '.' path with
  | [] -> path
  | head :: _ when !in_overflow && not (List.mem head units) -> path
  | head :: rest -> String.concat "." (unit_path head :: rest)

(* The top-level modules [t] aliases. *)
let rec aliased = function
  | Plan.Sig { items; _ } | Plan.Whole (_, items) | Plan.Functor { items; _ } ->
      List.concat_map
        (function
          | Plan.Rewired (_, target) ->
              [ List.hd (String.split_on_char '.' target) ]
          | Plan.Sub (_, t) -> aliased t
          | Plan.Refused _ | Plan.Retyped _ | Plan.Removed _ -> [])
        items
  | Plan.Gone -> []

(* Each module after the modules of the list it aliases. *)
let rec ordered ready = function
  | [] -> List.rev ready
  | pending ->
      let now, later =
        List.partition
          (fun (_, t) ->
            List.for_all (fun a -> not (List.mem_assoc a pending)) (aliased t))
          pending
      in
      if now = [] then failwith "cyclic aliases between restated modules";
      ordered (List.rev_append now ready) later

let type_params n =
  match List.init n (fun i -> Printf.sprintf "'%c" (Char.chr (97 + i))) with
  | [] -> ""
  | [ a ] -> a ^ " "
  | l -> "(" ^ String.concat ", " l ^ ") "

let constraints buf depth = function
  | [] -> ()
  | c :: cs ->
      line buf depth "with %s" c;
      List.iter (fun c -> line buf (depth + 1) "and %s" c) cs

let type_removal orig (t, n) =
  let ps = type_params n in
  Printf.sprintf "type %s%s := %s%s.%s" ps t ps orig t

let module_removal orig m = Printf.sprintf "module %s := %s.%s" m orig m

(* The submodules of [orig] that the items restate, rewire or remove. *)
let replaced items =
  List.filter_map
    (function
      | Plan.Sub (m, _) | Plan.Rewired (m, _) | Plan.Removed m -> Some m
      | Plan.Refused _ | Plan.Retyped _ -> None)
    items

let include_mli buf depth orig cs =
  line buf depth "include module type of struct";
  line buf (depth + 2) "include %s" orig;
  line buf (depth + 1) "end";
  constraints buf (depth + 1) cs

let include_ml buf depth orig = function
  | [] -> line buf depth "include %s" orig
  | cs ->
      line buf depth "include (";
      line buf (depth + 1) "%s :" orig;
      line buf (depth + 2) "module type of struct";
      line buf (depth + 3) "include %s" orig;
      line buf (depth + 2) "end";
      constraints buf (depth + 2) cs;
      line buf depth ")"

(* {1 Interfaces} *)

let kind = Policy.kind_name

let refused_mli buf depth ~types v (r : Policy.refusal) =
  line buf depth "val %s : %s" (value_name v) (types (kind r.kind));
  line buf depth "[@@alert %s %S]" (kind r.kind) r.message;
  line buf depth ""

(* [typ] with each [{orig}] replaced by [orig]. *)
let subst_orig orig typ =
  let b = Buffer.create (String.length typ) in
  let n = String.length typ in
  let rec go i =
    if i >= n then ()
    else if i + 6 <= n && String.sub typ i 6 = "{orig}" then (
      Buffer.add_string b orig;
      go (i + 6))
    else (
      Buffer.add_char b typ.[i];
      go (i + 1))
  in
  go 0;
  Buffer.contents b

let retyped_mli buf depth orig name typ doc =
  let typ = subst_orig orig typ in
  line buf depth "val %s : %s" (value_name name) typ;
  comment buf depth doc;
  line buf depth ""

let params_text params =
  String.concat " "
    (List.map (fun (p, t) -> Printf.sprintf "(%s : %s)" p t) params)

let args_text params =
  String.concat " " (List.map (fun (p, _) -> Printf.sprintf "(%s)" p) params)

(* A functor's application as a type path spells it: [F(A)(B)]. *)
let type_args params =
  String.concat "" (List.map (fun (p, _) -> Printf.sprintf "(%s)" p) params)

(* The library a module of the original comes from: the unix library's
   Unix and UnixLabels, or the standard library. *)
let library orig =
  if String.starts_with ~prefix:"Unix" orig then "The unix library's"
  else if
    String.starts_with ~prefix:"Thread" orig
    || String.starts_with ~prefix:"Event" orig
  then "The threads library's"
  else "The standard library's"

let restated_doc orig = function
  | Plan.Whole (r, _) ->
      Printf.sprintf "Every value of %s {!%s} is refused. %s"
        (String.lowercase_ascii (library orig))
        orig r.message
  | Plan.Gone ->
      Printf.sprintf
        "%s {!%s} cannot be restated by this version of hermetic, so the \
         prelude declares it empty."
        (library orig) orig
  | Plan.Sig { items; _ } | Plan.Functor { items; _ } ->
      let what =
        if List.for_all (function Plan.Refused _ -> true | _ -> false) items
        then "the values below refused"
        else "the names below restated"
      in
      Printf.sprintf "%s {!%s}, with %s; the others are {!%s}'s." (library orig)
        orig what orig

let values_include buf depth orig (n : Plan.names) =
  let cs =
    List.map (type_removal orig) n.types
    @ List.map
        (fun m -> Printf.sprintf "module type %s := %s.%s" m orig m)
        n.module_types
    @ List.map (module_removal orig) n.submodules
  in
  if cs <> [] && not n.class_types then (
    line buf depth "(** @inline *)";
    include_mli buf depth orig cs;
    line buf 0 "")

let sig_open = function
  | Plan.Functor { params; _ } -> params_text params ^ " : sig"
  | Plan.Sig _ | Plan.Whole _ | Plan.Gone -> ": sig"

let rec items_mli buf depth ~types ~type_orig orig items =
  List.iter
    (function
      | Plan.Refused (v, r) -> refused_mli buf depth ~types v r
      | Plan.Retyped { name; typ; doc; _ } ->
          retyped_mli buf depth type_orig name typ doc
      | Plan.Removed _ -> ()
      | Plan.Rewired (m, target) ->
          line buf depth "module %s = %s" m (restated_path target);
          line buf depth ""
      | Plan.Sub (m, t) ->
          comment buf depth (restated_doc (orig ^ "." ^ m) t);
          line buf depth "module %s %s" m (sig_open t);
          body_mli buf (depth + 1) ~types (orig ^ "." ^ m) t;
          line buf depth "end";
          line buf depth "")
    items

(* The body of a restated module: the original, its first include hidden
   from the documentation, then the values with the original's own types,
   then the items. *)
and body_mli buf depth ~types orig = function
  | Plan.Gone -> ()
  | Plan.Functor { params; items } ->
      (* The result's signature, not its strengthened module type, so that
         an anonymous argument can be eliminated. *)
      line buf depth "include module type of %s %s" orig (args_text params);
      line buf 0 "";
      items_mli buf depth ~types ~type_orig:(orig ^ type_args params) orig items
  | Plan.Sig { items; names } ->
      line buf depth "(**/**)";
      line buf 0 "";
      include_mli buf depth orig
        (List.map (module_removal orig) (replaced items));
      line buf 0 "";
      line buf depth "(**/**)";
      line buf 0 "";
      values_include buf depth orig names;
      items_mli buf depth ~types ~type_orig:orig orig items
  | Plan.Whole (_, items) ->
      line buf depth "(**/**)";
      line buf 0 "";
      include_mli buf depth orig
        (List.map (module_removal orig) (replaced items));
      line buf 0 "";
      line buf depth "(**/**)";
      line buf 0 "";
      items_mli buf depth ~types ~type_orig:orig orig items

(* {1 Implementations} *)

let stub kind = Printf.sprintf "%s.%s" refused_unit (Policy.kind_name kind)

let struct_open = function
  | Plan.Functor { params; _ } -> params_text params ^ " = struct"
  | Plan.Sig _ | Plan.Whole _ | Plan.Gone -> "= struct"

let rec items_ml buf depth orig items =
  List.iter
    (function
      | Plan.Refused (v, r) ->
          line buf depth "let %s = %s" (value_name v) (stub r.kind)
      | Plan.Retyped { name; impl; _ } ->
          line buf depth "let %s = %s" (value_name name) impl
      | Plan.Removed _ -> ()
      | Plan.Rewired (m, target) ->
          line buf depth "module %s = %s" m (restated_path target)
      | Plan.Sub (m, t) ->
          line buf depth "module %s %s" m (struct_open t);
          body_ml buf (depth + 1) (orig ^ "." ^ m) t;
          line buf depth "end")
    items

and body_ml buf depth orig = function
  | Plan.Gone -> ()
  | Plan.Functor { params; items } ->
      line buf depth "include %s %s" orig (args_text params);
      items_ml buf depth orig items
  | Plan.Sig { items; _ } | Plan.Whole (_, items) ->
      include_ml buf depth orig
        (List.map (module_removal orig) (replaced items));
      items_ml buf depth orig items

(* {1 The units} *)

let unit_types k = Printf.sprintf "%s.%s" refused_unit k

let orig_of (plan : Plan.prelude) m =
  if List.mem m plan.in_stdlib then "Stdlib." ^ m else m

let unit_mli plan m t =
  let buf = Buffer.create 4096 in
  Buffer.add_string buf header;
  comment buf 0
    (restated_doc (orig_of plan m) t
    ^ Printf.sprintf "\n\n@canonical %s.%s" Policy.name m);
  line buf 0 "";
  body_mli buf 0 ~types:unit_types (orig_of plan m) t;
  Buffer.contents buf

let unit_ml plan m t =
  let buf = Buffer.create 4096 in
  Buffer.add_string buf header;
  body_ml buf 0 (orig_of plan m) t;
  Buffer.contents buf

let kept_unit m =
  header
  ^ Printf.sprintf
      "(* The standard library's %s is not restated by this compiler's \
       prelude. *)\n"
      m

(* The restated modules the policy does not name, as submodules. *)
let overflow_mli plan modules =
  in_overflow := true;
  let modules = ordered [] modules in
  let buf = Buffer.create 4096 in
  Buffer.add_string buf header;
  comment buf 0 "The restated modules this version of hermetic does not name.";
  line buf 0 "";
  List.iter
    (fun (m, t) ->
      let orig = orig_of plan m in
      comment buf 0 (restated_doc orig t);
      line buf 0 "module %s %s" m (sig_open t);
      body_mli buf 1 ~types:unit_types orig t;
      line buf 0 "end";
      line buf 0 "")
    modules;
  in_overflow := false;
  Buffer.contents buf

let overflow_ml plan modules =
  in_overflow := true;
  let modules = ordered [] modules in
  let buf = Buffer.create 4096 in
  Buffer.add_string buf header;
  List.iter
    (fun (m, t) ->
      line buf 0 "module %s %s" m (struct_open t);
      body_ml buf 1 (orig_of plan m) t;
      line buf 0 "end")
    modules;
  in_overflow := false;
  Buffer.contents buf

let refused_mli_unit =
  header
  ^ Printf.sprintf
      "(** The types of refused values, which the prelude re-exports. *)\n\n\
       type ambient\n\
       (** @canonical %s.ambient *)\n\n\
       type unsafe\n\
       (** @canonical %s.unsafe *)\n\n\
       type unreviewed\n\
       (** @canonical %s.unreviewed *)\n\n\
       (**/**)\n\n\
       val ambient : ambient\n\
       val unsafe : unsafe\n\
       val unreviewed : unreviewed\n"
      Policy.name Policy.name Policy.name

let refused_ml_unit =
  header
  ^ "type ambient = unit\n\
     type unsafe = unit\n\
     type unreviewed = unit\n\n\
     let ambient = ()\n\
     let unsafe = ()\n\
     let unreviewed = ()\n"

(* {1 The prelude} *)

let type_docs =
  [
    ( "ambient",
      "The type for values refused because they reach an Eio capability \
       without being handed it." );
    ( "unsafe",
      "The type for values refused because they can forge memory or a value of \
       any type." );
    ( "unreviewed",
      "The type for values this version of hermetic has not reviewed, which a \
       newer compiler added." );
  ]

let types_mli buf =
  List.iter
    (fun (k, doc) ->
      line buf 0 "type %s = %s.%s" k refused_unit k;
      comment buf 0 doc;
      line buf 0 "")
    type_docs

let removals (plan : Plan.prelude) =
  List.map (module_removal "Stdlib") plan.in_stdlib

let aliases buf depth names =
  List.iter (fun m -> line buf depth "module %s = %s" m (unit_path m)) names

let main_types k = k

let preamble_mli buf =
  Buffer.add_string buf header;
  comment buf 0 Policy.doc;
  line buf 0 "";
  line buf 0 "(** {1:types Refused values} *)";
  line buf 0 "";
  types_mli buf;
  line buf 0 "(** {1:escape Escaping the prelude} *)";
  line buf 0 "";
  comment buf 0
    "[Stdlib_original] is [Stdlib] without refusals. Name it only for an \
     audited use: [grep Stdlib_original] finds each line that names it, but an \
     alias such as [module S = Stdlib_original] hides the uses after it.";
  line buf 0 "module Stdlib_original = Stdlib";
  line buf 0 ""

(* The libraries that reach the system past Eio's capabilities, declared
   empty. *)
let shadowed_mli buf =
  line buf 0 "(** {1:past Past the capabilities} *)";
  line buf 0 "";
  comment buf 0
    "The libraries that reach the system past Eio's capabilities, declared \
     empty, so that each of their names is unbound. The prelude does not \
     depend on them.";
  line buf 0 "";
  List.iter
    (fun (m, message) ->
      line buf 0 "module %s : sig end" m;
      line buf 0 "[@@alert ambient %S]" message;
      line buf 0 "")
    Policy.shadowed

let stdlib_mli buf (plan : Plan.prelude) =
  line buf 0 "(** {1:stdlib The standard library} *)";
  line buf 0 "";
  comment buf 0
    "The standard library with the refusals above. A path through [Stdlib], an \
     [open Stdlib] and an [include Stdlib] reach this module.";
  line buf 0 "module Stdlib : sig";
  include_mli buf 1 "Stdlib" (removals plan);
  line buf 0 "";
  items_mli buf 1 ~types:main_types ~type_orig:"Stdlib" "Stdlib" plan.values;
  aliases buf 1 plan.in_stdlib;
  line buf 0 "end";
  line buf 0 ""

let main_mli (plan : Plan.prelude) =
  let buf = Buffer.create 65536 in
  preamble_mli buf;
  line buf 0 "(** {1:restated Restated modules and values} *)";
  line buf 0 "";
  comment buf 0
    "The modules and values of the standard library that the prelude restates. \
     Every other name is left to the standard library, so that a type a source \
     file names or infers through it is the standard library's own.";
  line buf 0 "";
  aliases buf 0 (List.map fst plan.modules);
  line buf 0 "";
  items_mli buf 0 ~types:main_types ~type_orig:"Stdlib" "Stdlib" plan.values;
  shadowed_mli buf;
  stdlib_mli buf plan;
  line buf 0 "(**/**)";
  line buf 0 "";
  List.iter
    (fun m -> line buf 0 "module Stdlib__%s = %s" m (unit_path m))
    plan.in_stdlib;
  Buffer.contents buf

let main_ml (plan : Plan.prelude) =
  let buf = Buffer.create 65536 in
  Buffer.add_string buf header;
  List.iter
    (fun (k, _) -> line buf 0 "type %s = %s.%s" k refused_unit k)
    type_docs;
  line buf 0 "";
  line buf 0 "module Stdlib_original = Stdlib";
  aliases buf 0 (List.map fst plan.modules);
  items_ml buf 0 "Stdlib" plan.values;
  List.iter
    (fun (m, _) -> line buf 0 "module %s = struct end" m)
    Policy.shadowed;
  line buf 0 "";
  line buf 0 "module Stdlib = struct";
  include_ml buf 1 "Stdlib" (removals plan);
  items_ml buf 1 "Stdlib" plan.values;
  aliases buf 1 plan.in_stdlib;
  line buf 0 "end";
  line buf 0 "";
  List.iter
    (fun m -> line buf 0 "module Stdlib__%s = %s" m (unit_path m))
    plan.in_stdlib;
  Buffer.contents buf

let unit_files plan m =
  let base = prefix ^ "__" ^ m in
  match List.assoc_opt m plan.Plan.modules with
  | Some t ->
      [ (base ^ ".mli", unit_mli plan m t); (base ^ ".ml", unit_ml plan m t) ]
  | None -> [ (base ^ ".mli", kept_unit m); (base ^ ".ml", kept_unit m) ]

let files (plan : Plan.prelude) =
  let extra = List.filter (fun (m, _) -> not (List.mem m units)) plan.modules in
  [
    (prefix ^ ".mli", main_mli plan);
    (prefix ^ ".ml", main_ml plan);
    (prefix ^ "__Refused.mli", refused_mli_unit);
    (prefix ^ "__Refused.ml", refused_ml_unit);
    (prefix ^ "__" ^ overflow ^ ".mli", overflow_mli plan extra);
    (prefix ^ "__" ^ overflow ^ ".ml", overflow_ml plan extra);
  ]
  @ List.concat_map (unit_files plan) units

let file_names =
  [
    prefix ^ ".ml";
    prefix ^ ".mli";
    prefix ^ "__Refused.ml";
    prefix ^ "__Refused.mli";
    prefix ^ "__" ^ overflow ^ ".ml";
    prefix ^ "__" ^ overflow ^ ".mli";
  ]
  @ List.concat_map
      (fun m -> [ prefix ^ "__" ^ m ^ ".ml"; prefix ^ "__" ^ m ^ ".mli" ])
      units

let dune ~gen =
  let buf = Buffer.create 4096 in
  line buf 0
    "; Generated by gen --dune from the policy: the files the generator";
  line buf 0 "; writes, a unit for each module the policy names. Do not edit.";
  line buf 0 "";
  line buf 0 "(rule";
  line buf 0 " (targets";
  List.iter (fun f -> line buf 0 "  %s" f) (List.sort String.compare file_names);
  line buf 0 " )";
  line buf 0 " (deps";
  line buf 0 "  (glob_files %%{ocaml_where}/*.cmi)";
  line buf 0 "  (glob_files %%{ocaml_where}/unix/*.cmi)";
  line buf 0 "  (glob_files %%{ocaml_where}/threads/*.cmi))";
  line buf 0 " (action";
  line buf 0 "  (run %s %%{ocaml_where} .)))" gen;
  Buffer.contents buf
